#include <iostream>
#include <vector>

int main() {
    std::vector<int> datos{1, 4, 7};

    if (datos.empty()) {
        std::cout << "Sin datos";
        return 0;
    }

    int suma{0};
    int minimo{datos[0]};
    int maximo{datos[0]};

    for (int dato : datos) {
        suma += dato;
        if (dato < minimo) {
            minimo = dato;
        }
        if (dato > maximo) {
            maximo = dato;
        }
    }

    int cantidad{static_cast<int>(datos.size())};
    double media{static_cast<double>(suma) / cantidad};
    bool dentro{media >= minimo && media <= maximo};

    std::cout << "Suma=" << suma << " Media=" << media
              << " Minimo=" << minimo << " Maximo=" << maximo
              << " Dentro=" << dentro;

    return 0;
}

#include <iostream>
#include <vector>

void informar(const std::vector<int>& datos) {
    if (datos.empty()) {
        std::cout << "Sin datos\n";
        return;
    }

    int suma{0};
    int minimo{datos[0]};
    int maximo{datos[0]};

    for (int dato : datos) {
        suma += dato;
        if (dato < minimo) {
            minimo = dato;
        }
        if (dato > maximo) {
            maximo = dato;
        }
    }

    int cantidad{static_cast<int>(datos.size())};
    double media{static_cast<double>(suma) / cantidad};
    bool dentro{media >= minimo && media <= maximo};

    std::cout << "Suma=" << suma << " Media=" << media
              << " Minimo=" << minimo << " Maximo=" << maximo
              << " Dentro=" << dentro << "\n";
}

int main() {
    informar({1, 4, 7});
